# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
"""Linear adapter — maps synaptory artifacts onto a Linear team.

Mapping:
- Epic     -> Issue labelled `hc:epic` + `EPIC-001`
- Story    -> Issue labelled `hc:story` + `US-037`, linked to its epic by the
              `EPIC-001` label
- Task/Bug -> Issue labelled `hc:task` / `hc:bug`
- Sprint   -> Linear Cycle (native integer `number` — no name parsing)
- Status   -> Linear WorkflowState, resolved in three tiers (see _resolve_state)
- Priority -> Linear native priority (0-4)
- Points   -> Linear `estimate`, only when the team enables estimation

Epic linkage is **label-only** — deliberately not `parentId` and not a Linear
Project. Linear Projects cannot carry IssueLabels (so an epic-as-Project could
not hold its canonical `EPIC-001` id), and `projectCreate` mutates the
workspace roadmap. Keeping epics on labels leaves `parent` free for real
sub-tasks and reserves Projects as a multi-spec discriminator.

ID convention:
  The Synaptory ID (e.g. US-037) is the canonical cross-adapter identifier.
  It is stored as a `US-037` label for server-side filtering, and repeated in
  a `> synaptory: US-037` first line of the description as a recovery path if
  the label is removed. Linear's uuid is an internal implementation detail;
  `tracker-id-map.json` holds both it and the human `ENG-123` identifier.
"""

import json
import re
import sys
from pathlib import Path
from typing import Optional

from .base import (
    ArtifactAdapter, Epic, Story, SprintInfo, BacklogItem,
    AcceptanceCriterion, SprintMetrics, QueryFilter,
    AdapterError, AdapterAuthError, AdapterOfflineError,
)
from .transport.linear_transport import LinearTransport, _norm_status


# ── Linear Mappings ──────────────────────────────────────────────────────

# Synaptory priority -> Linear priority (0 = none, 1 = urgent … 4 = low)
PRIORITY_MAP = {
    "Must":   1,   # Urgent
    "Should": 2,   # High
    "Could":  3,   # Medium
    "Won't":  4,   # Low
}
PRIORITY_REVERSE = {v: k for k, v in PRIORITY_MAP.items()}

# Canonical synaptory state -> preferred Linear WorkflowState *name*.
# Tier 2 of resolution: matched case- and separator-insensitively, so a team
# using "In Review" / "IN REVIEW" / "in-review" needs no status_map entry.
STATUS_MAP = {
    "BACKLOG":             "Backlog",
    "TO_DO":               "Todo",
    "IN_PROGRESS":         "In Progress",
    "IN_REVIEW":           "In Review",
    "AWAITING_ACCEPTANCE": "Awaiting Acceptance",
    "BLOCKED":             "",   # label-only — never a state move
    "DONE":                "Done",
    "COMPLETED":           "Done",
    "CANCELLED":           "Canceled",
}

# Linear state name -> canonical synaptory state, for read-back. Seeded with
# Linear's own state-*type* vocabulary plus the custom names teams commonly
# pick, so most workflows read back correctly with no configuration.
STATUS_REVERSE = {
    "backlog":             "BACKLOG",
    "triage":              "BACKLOG",
    "todo":                "TO_DO",
    "to do":               "TO_DO",
    "unstarted":           "TO_DO",
    "open":                "TO_DO",
    "up next":             "TO_DO",
    "in progress":         "IN_PROGRESS",
    "started":             "IN_PROGRESS",
    "doing":               "IN_PROGRESS",
    "in review":           "IN_REVIEW",
    "review":              "IN_REVIEW",
    "code review":         "IN_REVIEW",
    "peer review":         "IN_REVIEW",
    "in qa":               "IN_REVIEW",
    "awaiting acceptance": "AWAITING_ACCEPTANCE",
    "pending acceptance":  "AWAITING_ACCEPTANCE",
    "po review":           "AWAITING_ACCEPTANCE",
    "done":                "DONE",
    "completed":           "DONE",
    "shipped":             "DONE",
    "canceled":            "DONE",
    "cancelled":           "DONE",
    "duplicate":           "DONE",
}
_STATUS_REVERSE_NORM = {_norm_status(k): v for k, v in STATUS_REVERSE.items()}

# Tier 3: when neither an override nor a built-in *name* matches, resolve by
# the state's `type` — the tier that makes fully custom workflows work with no
# configuration. `pick` orders candidates by `position`.
STATUS_TYPE_FALLBACK = {
    "BACKLOG":             ("backlog",   "first"),
    "TO_DO":               ("unstarted", "first"),
    "IN_PROGRESS":         ("started",   "first"),
    "IN_REVIEW":           ("started",   "last"),
    "AWAITING_ACCEPTANCE": ("started",   "last"),
    "DONE":                ("completed", "first"),
    "COMPLETED":           ("completed", "first"),
    "CANCELLED":           ("canceled",  "first"),
}

# Among `started` states, these name shapes are preferred for the review-ish
# canonical states before falling back to "last started state by position".
_REVIEW_NAME_RE = re.compile(r"review|qa|verif", re.I)
_ACCEPTANCE_NAME_RE = re.compile(r"awaiting|acceptance|sign.?off|po review", re.I)

# Label-backed status axis. Mirrors the Teamwork tag approach: these states
# are recorded as labels *in addition to* whatever workflow state resolves, so
# read-back stays faithful even when a team has no dedicated column.
STATUS_LABELS = {
    "BLOCKED":             "blocked",
    "IN_REVIEW":           "in-review",
    "AWAITING_ACCEPTANCE": "awaiting-acceptance",
    "CANCELLED":           "cancelled",
}

# Linear has no native issue-type field, so entity kind rides on a label the
# way Teamwork carries it on a tag. Prefix is configurable via label_prefix.
ENTITY_LABELS = {
    "epic":        "epic",
    "story":       "story",
    "task":        "task",
    "bug":         "bug",
    "subtask":     "task",
    "enhancement": "story",
}

# Estimate scales. Linear stores an int whose *meaning* depends on the team's
# issueEstimationType, so the T-shirt size must map differently per scale.
SIZE_TO_POINTS_BY_SCALE = {
    "fibonacci":   {"S": 1, "M": 3, "L": 5, "XL": 8},
    "linear":      {"S": 1, "M": 3, "L": 5, "XL": 8},
    "exponential": {"S": 1, "M": 2, "L": 4, "XL": 8},
    "tShirt":      {"S": 1, "M": 2, "L": 3, "XL": 4},
}
SIZE_TO_POINTS = SIZE_TO_POINTS_BY_SCALE["fibonacci"]
POINTS_TO_SIZE = {v: k for k, v in SIZE_TO_POINTS.items()}

_SYNAPTORY_ID_RE = re.compile(r'^(US|EPIC|FEAT|BUG|ENH|TASK|S\d+)-\w+$')
_EPIC_ID_RE = re.compile(r'^EPIC-\w+$')
_FEATURE_ID_RE = re.compile(r'^FEAT-\w+$')

_ENTITY_TYPE_PREFIXES = {
    "B-": "bug", "BUG-": "bug",
    "EPIC-": "epic",
    "T-": "task", "TASK-": "task",
}

# Linear state types that count as finished, for velocity + rollover.
_TERMINAL_STATE_TYPES = {"completed", "canceled"}

# Per-cycle issue budget used to size the one flat cycle-issues query. The
# whole point of that query is that it covers every cycle at once, so its cap
# must scale with cycle count — a fixed cap silently drops older sprints.
_MAX_ISSUES_PER_CYCLE = 250


def _detect_entity_type(entity_id: str) -> str:
    """Detect entity type from ID prefix. Returns 'story' as default."""
    upper = entity_id.upper()
    for prefix, etype in _ENTITY_TYPE_PREFIXES.items():
        if upper.startswith(prefix):
            return etype
    return "story"


def _clean_title(raw_title: str) -> str:
    """Strip the synaptory ID prefix from a title."""
    m = re.match(r'^[A-Z]+-\w+\s*[—–\-:]\s*', raw_title)
    if m:
        return raw_title[m.end():].strip()
    return raw_title


_DEFAULT_STORY_SECTIONS = [
    "Story", "Objective", "User Impact Statement",
    "Acceptance Criteria", "Business Rules", "Testing Notes",
    "Technical Context", "Data Model", "NFRs", "Feature List",
    "Dependencies", "UI Reference",
]


def _load_template_sections(template_path: str) -> list[str]:
    """Extract ## heading names from a tracker template file.

    Returns the ordered list of section headings found in the template.
    Falls back to empty list if the file doesn't exist or contains no headings.
    """
    p = Path(template_path) if template_path else None
    if not p or not p.exists():
        return []
    try:
        text = p.read_text(encoding="utf-8")
    except OSError:
        return []
    sections = []
    for line in text.splitlines():
        m = re.match(r'^##\s+(.+)', line.strip())
        if m:
            heading = re.sub(r'\{\{.*?\}\}', '', m.group(1).strip()).strip()
            if heading:
                sections.append(heading)
    return sections or []


def _extract_md_section(text: str, heading: str) -> str:
    """Extract content under a markdown heading until next same-level heading."""
    lines = text.splitlines()
    in_section = False
    section_lines = []
    heading_level = 0
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("#"):
            hashes = len(stripped) - len(stripped.lstrip("#"))
            title = stripped.lstrip("#").strip()
            if title.lower() == heading.lower():
                in_section = True
                heading_level = hashes
                continue
            elif in_section and hashes <= heading_level:
                break
        if in_section:
            section_lines.append(line)
    return "\n".join(section_lines).strip()


def _build_description(entity_id: str, feature: str = "",
                       raw_text: str = "",
                       template_path: str = "") -> str:
    """Build a rich Markdown description from story/epic Markdown source.

    Unlike Jira (which needs an ADF round trip), Linear stores raw Markdown —
    so this output is stored verbatim and the `> synaptory:` metadata line
    survives losslessly, making it a reliable ID-recovery path.
    """
    parts = [f"> synaptory: {entity_id}"]
    if feature:
        parts[0] += f" | Feature: {feature}"

    if raw_text:
        sections = _load_template_sections(template_path) or _DEFAULT_STORY_SECTIONS
        for section_name in sections:
            section = _extract_md_section(raw_text, section_name)
            if section:
                parts.append(f"\n## {section_name}\n\n{section}")

    return "\n".join(parts)


class LinearAdapter(ArtifactAdapter):
    """Adapter using Linear for ticket tracking."""

    def __init__(self, project_dir: Path, config, spec=None):
        """Construct the adapter.

        spec — optional SpecConfig (multi-spec mode). When set, the adapter
        scopes every read to the spec's filter, applies the corresponding
        write side-effect on issue creation, and routes its cache files to
        `.synaptory/.orchestrator/specs/{spec.id}/`.
        """
        super().__init__(project_dir, config)
        self.spec = spec
        lin_cfg = spec.linear if (spec is not None and spec.linear is not None) \
            else config.linear
        self._linear_cfg = lin_cfg

        self._status_map_override = dict(getattr(lin_cfg, "status_map", {}) or {})
        self._status_reverse_override = {
            _norm_status(name): canon
            for canon, name in self._status_map_override.items() if name
        }
        self._entity_label_overrides = dict(
            getattr(lin_cfg, "issue_type_overrides", {}) or {}
        )
        self._label_prefix = getattr(lin_cfg, "label_prefix", "hc:") or ""
        self._manage_cycles = bool(getattr(lin_cfg, "manage_cycles", False))
        self._cycle_length_days = int(getattr(lin_cfg, "cycle_length_days", 14) or 14)
        self._default_project_id = getattr(lin_cfg, "project_id", "") or ""

        # Fall back to the top-level team when a spec omits it — mirrors the
        # `github.repo` / `teamwork.project_id` fallback in _validate_specs.
        team_key = lin_cfg.team_key or getattr(config.linear, "team_key", "")
        team_id = lin_cfg.team_id or getattr(config.linear, "team_id", "")
        self.team_key = team_key
        self.transport = LinearTransport(team_key=team_key, team_id=team_id)

        self._states: Optional[list[dict]] = None
        self._id_map: Optional[dict] = None
        self._cycles_cache: Optional[list[dict]] = None

        if spec is not None:
            spec_dir = project_dir / ".synaptory" / ".orchestrator" / "specs" / spec.id
            self._id_map_path = spec_dir / "tracker-id-map.json"
            self._backlog_order_path = spec_dir / "backlog-order.json"
            self._local_cache_path = spec_dir / "tracker-data.json"
        else:
            orch = project_dir / ".synaptory" / ".orchestrator"
            self._id_map_path = orch / "tracker-id-map.json"
            self._backlog_order_path = orch / "backlog-order.json"
            self._local_cache_path = orch / "tracker-data.json"

    # ── Entity-label resolution ──────────────────────────────

    def _entity_label(self, entity_type: str) -> str:
        """Resolve the label that types an issue as a given synaptory entity."""
        override = self._entity_label_overrides.get(entity_type)
        if override:
            return override
        base = ENTITY_LABELS.get(entity_type, "story")
        return f"{self._label_prefix}{base}"

    # ── Spec filter helpers ──────────────────────────────────

    def _spec_filter_fragment(self) -> dict:
        """IssueFilter fragment scoping a read to the active spec.

        Returns `{}` when no spec is configured. Unlike Jira (which joins JQL
        *strings*), Linear composes nested filter *dicts* — callers merge with
        `_merge_filters`.
        """
        if self.spec is None:
            return {}
        ftype = self.spec.filter.type
        value = self.spec.filter.value
        if not value:
            return {}
        if ftype == "label":
            return {"labels": {"name": {"eq": value}}}
        if ftype == "project":
            # Accept either a Linear project uuid or its human name.
            key = "id" if _looks_like_uuid(value) else "name"
            return {"project": {key: {"eq": value}}}
        return {}

    def _ensure_spec_writeable(self, op: str) -> None:
        """Refuse writes for read-only spec filter types.

        Both Linear filter types (`label`, `project`) are writeable today —
        this guard exists so a future read-only type (e.g. a raw IssueFilter)
        cannot silently create issues outside the spec's scope.
        """
        if self.spec is None:
            return
        from .config import _READONLY_FILTER_TYPES
        if self.spec.filter.type in _READONLY_FILTER_TYPES:
            raise AdapterError(
                f"Spec {self.spec.id!r} uses filter.type={self.spec.filter.type!r} "
                f"which is read-only; refusing {op}. Switch the spec to "
                "label/project to enable writes."
            )

    def _apply_spec_write_side_effect(
        self, *, labels: list, extra_input: Optional[dict] = None,
    ) -> tuple[list, dict]:
        """Apply the spec's write side-effect for issue creation.

        - label   → appends the spec label to `labels` (deduped)
        - project → sets `projectId` on the create input
        """
        extra_input = dict(extra_input or {})
        if self.spec is not None:
            ftype = self.spec.filter.type
            value = self.spec.filter.value
            if ftype == "label":
                if value and value not in labels:
                    labels.append(value)
            elif ftype == "project" and value:
                # Reads accept a project *name*, but IssueCreateInput.projectId
                # requires the uuid — copying the raw name through silently
                # produced issues outside the spec's project.
                extra_input["projectId"] = self.transport.resolve_project_id(value)
        if self._default_project_id:
            extra_input.setdefault(
                "projectId",
                self.transport.resolve_project_id(self._default_project_id),
            )
        return labels, extra_input

    @staticmethod
    def _merge_filters(*fragments: dict) -> dict:
        """Combine IssueFilter fragments into one filter.

        Distinct keys merge flatly. Keys that *collide* are pushed into
        Linear's `and:` array instead of overwriting — a plain `dict.update`
        would silently drop one of them, and the common case is exactly a
        collision: the spec's `label` filter and the entity-type `label`
        filter both key on `labels`, so the spec scope would vanish and the
        query would widen to the whole team.
        """
        out: dict = {}
        conjuncts: list = []
        for frag in fragments:
            if not frag:
                continue
            for key, value in frag.items():
                if key == "and" and isinstance(value, list):
                    conjuncts.extend(value)
                elif key in out:
                    if out[key] != value:
                        conjuncts.append({key: value})
                else:
                    out[key] = value
        if conjuncts:
            out["and"] = out.get("and", []) + conjuncts
        return out

    # ── Lifecycle ─────────────────────────────────────────────

    def initialize(self) -> None:
        """Verify auth and load the team's workflow states and labels."""
        if not self.transport.check_api():
            raise AdapterAuthError(
                "Linear API not configured. Required:\n"
                "  LINEAR_API_KEY — Linear → Settings → Security & access → "
                "Personal API keys\n"
                "  .synaptory.yaml tracker.linear.team_key — your Linear team "
                "key (e.g. ENG)\n\n"
                "Tip: use direnv for project-scoped keys:\n"
                "  echo 'export LINEAR_API_KEY=\"lin_api_...\"' > .envrc && "
                "direnv allow .\n"
                "  Add .envrc to .gitignore."
            )
        self._load_states(refresh=True)

    def health_check(self) -> dict:
        out = self.transport.health_check()
        out["backend"] = "linear"
        if self.spec is not None:
            out["spec"] = self.spec.id
        return out

    def _load_states(self, refresh: bool = False) -> list[dict]:
        if self._states is None or refresh:
            self._states = self.transport.list_workflow_states()
        return self._states

    # ── Status resolution ────────────────────────────────────

    def _resolve_state(self, canonical: str) -> Optional[dict]:
        """Resolve a canonical synaptory state to a Linear WorkflowState.

        Three tiers, in order:
          1. `tracker.linear.status_map` override (per-spec wins over top-level)
          2. the built-in STATUS_MAP name
          3. the state's `type`, per STATUS_TYPE_FALLBACK

        Returns None when nothing resolves — callers degrade to a label-only
        update rather than raising, because `sync_tracker_status` is
        best-effort and a raise here would wedge the pipeline hook.
        """
        states = self._load_states()
        if not states:
            return None

        by_norm_name = {_norm_status(s.get("name", "")): s for s in states}

        # Tier 1 — explicit override.
        override = self._status_map_override.get(canonical)
        if override:
            hit = by_norm_name.get(_norm_status(override))
            if hit:
                return hit

        # Tier 2 — built-in preferred name.
        preferred = STATUS_MAP.get(canonical)
        if preferred:
            hit = by_norm_name.get(_norm_status(preferred))
            if hit:
                return hit

        # Tier 3 — resolve by state type.
        fallback = STATUS_TYPE_FALLBACK.get(canonical)
        if not fallback:
            return None
        want_type, pick = fallback
        candidates = sorted(
            (s for s in states if s.get("type") == want_type),
            key=lambda s: s.get("position") or 0,
        )
        if not candidates:
            # AWAITING_ACCEPTANCE / IN_REVIEW have no started state to land on
            # — fall through to IN_PROGRESS so the issue at least advances.
            if canonical in ("AWAITING_ACCEPTANCE", "IN_REVIEW"):
                return self._resolve_state("IN_PROGRESS") if canonical != "IN_PROGRESS" else None
            return None

        if canonical == "AWAITING_ACCEPTANCE":
            for s in candidates:
                if _ACCEPTANCE_NAME_RE.search(s.get("name", "")):
                    return s
        if canonical in ("IN_REVIEW", "AWAITING_ACCEPTANCE"):
            for s in candidates:
                if _REVIEW_NAME_RE.search(s.get("name", "")):
                    return s
            # A single started state means there is no distinct review column;
            # returning it is the same as IN_PROGRESS, which is correct.
            return candidates[-1]

        return candidates[0] if pick == "first" else candidates[-1]

    def _canonical_from_issue(self, issue: dict) -> str:
        """Read an issue's canonical synaptory status back out.

        Label-backed states win over the workflow state: a team with no
        acceptance column lands AWAITING_ACCEPTANCE on the review state plus
        an `awaiting-acceptance` label, and the label is what distinguishes
        the two.
        """
        label_names = {n.casefold() for n in _label_names(issue)}
        state_type = (issue.get("state") or {}).get("type", "")
        # Order matters: a finished issue is DONE/CANCELLED regardless of a
        # stale `blocked` marker, so the terminal check runs first. Otherwise
        # BLOCKED wins over the review markers — same precedence as
        # teamwork_adapter and github_adapter.
        if state_type in _TERMINAL_STATE_TYPES:
            if STATUS_LABELS["CANCELLED"].casefold() in label_names \
                    or state_type == "canceled":
                return "DONE"
        else:
            for canonical in ("BLOCKED", "AWAITING_ACCEPTANCE"):
                marker = STATUS_LABELS.get(canonical, "")
                if marker and marker.casefold() in label_names:
                    # BLOCKED is reported as its own status (matching the other
                    # backends) so `get_sprint_metrics().blocked` is non-zero.
                    # `transitions.validate_transition` special-cases BLOCKED at
                    # either endpoint, so this does not break the audit gate.
                    return canonical

        state = issue.get("state") or {}
        name = state.get("name", "")
        norm = _norm_status(name)
        hit = self._status_reverse_override.get(norm) or _STATUS_REVERSE_NORM.get(norm)
        if hit:
            return hit
        # Unknown custom name — fall back to the state's type.
        return {
            "triage":    "BACKLOG",
            "backlog":   "BACKLOG",
            "unstarted": "TO_DO",
            "started":   "IN_PROGRESS",
            "completed": "DONE",
            "canceled":  "DONE",
        }.get(state.get("type", ""), "TODO")

    # ── Estimates ────────────────────────────────────────────

    def _size_to_estimate(self, size: str) -> Optional[int]:
        """Map a T-shirt size to a Linear estimate, or None when disabled.

        Returns None when the team has estimation turned off — sending
        `estimate` to a team with `issueEstimationType: notUsed` errors.
        """
        if not size:
            return None
        try:
            scale = self.transport.issue_estimation_type()
        except (AdapterError, AdapterAuthError, AdapterOfflineError):
            return None
        if scale == "notUsed":
            return None
        table = SIZE_TO_POINTS_BY_SCALE.get(scale, SIZE_TO_POINTS)
        return table.get(size)

    def _estimate_to_size(self, estimate) -> str:
        if estimate is None:
            return ""
        try:
            scale = self.transport.issue_estimation_type()
        except (AdapterError, AdapterAuthError, AdapterOfflineError):
            scale = "fibonacci"
        table = SIZE_TO_POINTS_BY_SCALE.get(scale, SIZE_TO_POINTS)
        reverse = {v: k for k, v in table.items()}
        try:
            return reverse.get(int(estimate), str(int(estimate)))
        except (ValueError, TypeError):
            return ""

    # ── Local cache ──────────────────────────────────────────

    def _update_local_cache_status(self, story_id: str, status: str) -> None:
        """Write-through the new status to tracker-data.json (best-effort)."""
        if not self._local_cache_path.exists():
            return
        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
            for s in data.get("stories", []):
                if s.get("id") == story_id:
                    s["status"] = status
                    break
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except (json.JSONDecodeError, OSError):
            pass  # cache is best-effort; don't fail the primary operation

    def sync_to_local_cache(self, sprint_num: Optional[int] = None) -> dict:
        """Pull current status from Linear and update tracker-data.json.

        Returns:
            dict with sync stats: {"synced": N, "added": N, "errors": [...]}
        """
        stats: dict = {"synced": 0, "added": 0, "errors": []}
        if not self._local_cache_path.exists():
            # Bootstrap an empty cache so the first sync in a fresh workspace
            # works (#108) — there is nothing local to migrate in that case.
            self._local_cache_path.parent.mkdir(parents=True, exist_ok=True)
            self._local_cache_path.write_text(
                json.dumps({"epics": [], "sprints": [], "stories": []}, indent=2),
                encoding="utf-8",
            )

        try:
            data = json.loads(self._local_cache_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError) as e:
            stats["errors"].append(f"Failed to read local cache: {e}")
            return stats

        local_stories = {s["id"]: s for s in data.get("stories", [])}

        if sprint_num is not None:
            live_stories = self.get_sprint_backlog(sprint_num)
        else:
            live_stories = self.list_stories()

        for story in live_stories:
            if story.id in local_stories:
                local_stories[story.id]["status"] = story.status
                stats["synced"] += 1
            else:
                data["stories"].append({
                    "id": story.id, "title": story.title,
                    "feature": story.feature, "epic": story.epic,
                    "priority": story.priority, "status": story.status,
                    "size": story.size, "sprint": story.sprint,
                    "ac_count": story.ac_count, "acceptance_criteria": [],
                    "raw_text": "",
                })
                stats["added"] += 1

        try:
            self._local_cache_path.write_text(
                json.dumps(data, indent=2, default=str), encoding="utf-8",
            )
        except OSError as e:
            stats["errors"].append(f"Failed to write local cache: {e}")

        return stats

    # ── Epic Operations ──────────────────────────────────────

    def list_epics(self) -> list[Epic]:
        issues = self._search_scoped(entity_type="epic", order_by="createdAt")
        return [self._issue_to_epic(i) for i in issues]

    def get_epic(self, epic_id: str) -> Optional[Epic]:
        linear_id = self._resolve_id(epic_id)
        if not linear_id:
            return None
        try:
            issue = self.transport.get_issue(linear_id)
            return self._issue_to_epic(issue) if issue else None
        except AdapterError:
            return None

    def create_epic(self, epic: Epic, raw_text: str = "") -> Epic:
        self._ensure_spec_writeable("create_epic")
        labels = [epic.id, self._entity_label("epic")]
        labels, extra_input = self._apply_spec_write_side_effect(labels=labels)

        description = _build_description(
            epic.id, raw_text=raw_text or epic.raw_text,
            template_path=self._resolve_template_path("epic"),
        )
        input_ = {
            "title": _clean_title(epic.title),
            "description": description,
            "labelIds": self._label_ids(labels),
        }
        input_.update(extra_input)

        issue = self.transport.create_issue(input_)
        epic.tracker_id = issue.get("identifier", "")
        epic.tracker_url = issue.get("url", "")
        self._save_id_mapping(
            epic.id, issue.get("id", ""),
            issue.get("identifier", ""), issue.get("url", ""),
        )
        return epic

    def update_epic(self, epic_id: str, **fields) -> Epic:
        linear_id = self._resolve_id(epic_id)
        if not linear_id:
            raise AdapterError(f"Epic not found in ID map: {epic_id}")
        updates = {}
        if "title" in fields:
            updates["title"] = _clean_title(fields["title"])
        if "description" in fields:
            updates["description"] = fields["description"]
        if updates:
            self.transport.update_issue(linear_id, updates)
        return self.get_epic(epic_id) or Epic(id=epic_id, title=fields.get("title", ""))

    # ── Story Operations ─────────────────────────────────────

    def list_stories(self, epic_id: Optional[str] = None,
                     sprint: Optional[int] = None) -> list[Story]:
        extra = None
        if epic_id:
            # Epic linkage is label-only, so scoping to an epic is a label
            # filter — no parent/child traversal involved.
            extra = {"labels": {"name": {"eq": epic_id}}}
        issues = self._search_scoped(extra)
        stories = [self._issue_to_story(i) for i in issues]
        if sprint is not None:
            stories = [s for s in stories if s.sprint == str(sprint)]
        return stories

    def get_story(self, story_id: str) -> Optional[Story]:
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            return None
        try:
            issue = self.transport.get_issue(linear_id)
            return self._issue_to_story(issue) if issue else None
        except AdapterError:
            return None

    def create_ticket(self, story: Story, raw_text: str = "") -> Story:
        self._ensure_spec_writeable("create_ticket")
        entity_type = _detect_entity_type(story.id)
        labels = [story.id, self._entity_label(entity_type)]
        if story.epic:
            labels.append(story.epic)      # epic linkage is a label
        if story.feature:
            labels.append(story.feature)
        labels, extra_input = self._apply_spec_write_side_effect(labels=labels)

        description = _build_description(
            story.id, feature=story.feature,
            raw_text=raw_text or story.raw_text,
            template_path=self._resolve_template_path(entity_type),
        )
        input_ = {
            "title": _clean_title(story.title),
            "description": description,
            "labelIds": self._label_ids(labels),
        }
        if story.priority in PRIORITY_MAP:
            input_["priority"] = PRIORITY_MAP[story.priority]
        estimate = self._size_to_estimate(story.size)
        if estimate is not None:
            input_["estimate"] = estimate
        if story.sprint:
            cycle = self._resolve_cycle(_safe_int(story.sprint))
            if cycle:
                input_["cycleId"] = cycle["id"]
        input_.update(extra_input)

        issue = self.transport.create_issue(input_)
        story.tracker_id = issue.get("identifier", "")
        story.tracker_url = issue.get("url", "")
        self._save_id_mapping(
            story.id, issue.get("id", ""),
            issue.get("identifier", ""), issue.get("url", ""),
        )
        if input_.get("cycleId"):
            # The cycles cache carries each cycle's issues, so a new issue
            # landing in a cycle makes it stale — same invalidation
            # assign_to_sprint does.
            self._cycles_cache = None
        return story

    def update_story_status(self, story_id: str, status: str, *,
                            allow_skip: bool = False) -> Story:
        self._validate_status_transition(story_id, status, allow_skip)
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            raise AdapterError(f"Story not found in ID map: {story_id}")

        state = self._resolve_state(status)
        updates: dict = {}
        if state:
            updates["stateId"] = state["id"]
        elif STATUS_MAP.get(status):
            # Tier 3 also missed — record the status on a label and keep going.
            # Raising here would wedge story_pipeline.sync_tracker_status.
            print(
                f"tracker(linear): no workflow state resolves for {status} on "
                f"team {self.team_key!r} — recording it as a label only. Set "
                "tracker.linear.status_map to map it onto one of your states.",
                file=sys.stderr,
            )

        # Label axis: apply this status's marker, drop the others so the read
        # path never sees two conflicting markers on one issue.
        issue = self.transport.get_issue(linear_id) or {}
        current = {n for n in _label_names(issue)}
        markers = set(STATUS_LABELS.values())
        keep = current - markers
        marker = STATUS_LABELS.get(status)
        if marker:
            keep.add(marker)
        if keep != current:
            updates["labelIds"] = self._label_ids(sorted(keep))

        if updates:
            self.transport.update_issue(linear_id, updates)

        self._update_local_cache_status(story_id, status)

        story = self.get_story(story_id)
        return story or Story(id=story_id, title=story_id, status=status)

    def update_story(self, story_id: str, **fields) -> Story:
        if "status" in fields:
            return self.update_story_status(story_id, fields["status"])
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            raise AdapterError(f"Story not found: {story_id}")
        updates: dict = {}
        if "title" in fields:
            updates["title"] = _clean_title(fields["title"])
        if "description" in fields:
            updates["description"] = fields["description"]
        if "priority" in fields and fields["priority"] in PRIORITY_MAP:
            updates["priority"] = PRIORITY_MAP[fields["priority"]]
        if "size" in fields:
            estimate = self._size_to_estimate(fields["size"])
            if estimate is not None:
                updates["estimate"] = estimate
        if updates:
            self.transport.update_issue(linear_id, updates)
        return self.get_story(story_id) or Story(id=story_id, title="")

    # ── Acceptance criteria ──────────────────────────────────

    def get_acceptance_criteria(self, story_id: str) -> list[AcceptanceCriterion]:
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            return []
        issue = self.transport.get_issue(linear_id)
        return self._parse_acs_from_description((issue or {}).get("description") or "")

    def update_acceptance_criteria(self, story_id: str, ac_id: str,
                                   met: bool) -> AcceptanceCriterion:
        """Tick or untick an AC checkbox in the issue description.

        Genuinely implementable here (unlike Jira, whose ADF round trip makes
        this a stub) because Linear stores descriptions as raw Markdown.
        """
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            raise AdapterError(f"Story not found: {story_id}")
        issue = self.transport.get_issue(linear_id) or {}
        description = issue.get("description") or ""

        mark = "x" if met else " "
        pattern = re.compile(
            r'^(\s*- \[)[xX ](\]\s*\*?\*?' + re.escape(ac_id) + r'\b)',
            re.MULTILINE,
        )
        updated, count = pattern.subn(rf'\g<1>{mark}\g<2>', description)
        if count:
            self.transport.update_issue(linear_id, {"description": updated})

        for ac in self._parse_acs_from_description(updated):
            if ac.id == ac_id:
                return ac
        return AcceptanceCriterion(id=ac_id, text="", met=met)

    # ── Task & Bug Operations ────────────────────────────────

    def create_aux_ticket(self, ticket_type: str, title: str,
                          parent_id: Optional[str] = None, **fields) -> dict:
        self._ensure_spec_writeable("create_aux_ticket")
        labels = [self._entity_label(ticket_type)]
        if ticket_type == "enhancement":
            labels.append("enhancement")
        if parent_id:
            labels.append(parent_id)
        labels, extra_input = self._apply_spec_write_side_effect(labels=labels)

        input_ = {
            "title": title,
            "description": fields.get("body", ""),
            "labelIds": self._label_ids(labels),
        }
        input_.update(extra_input)
        issue = self.transport.create_issue(input_)
        return {
            "id": issue.get("identifier", ""),
            "title": title,
            "type": ticket_type,
            "url": issue.get("url", ""),
        }

    def close_ticket(self, ticket_id: str, resolution: str = "") -> dict:
        linear_id = self._resolve_id(ticket_id) or ticket_id
        state = self._resolve_state("DONE")
        if state:
            self.transport.update_issue(linear_id, {"stateId": state["id"]})
        return {"id": ticket_id, "status": "DONE", "resolution": resolution}

    # ── Sprint (Cycle) Operations ────────────────────────────

    def _load_cycles(self, refresh: bool = False) -> list[dict]:
        """Fetch the team's cycles and attach their in-scope issues.

        Two flat calls, never per-cycle: `jira_adapter.list_sprints` does N+1,
        and at Linear's 1500 req/hour budget a 20-sprint velocity report would
        burn 40+ requests that way.

        The issues are fetched *separately* rather than through a nested
        `cycles { issues }` connection for two reasons:

        1. **Complexity.** Linear multiplies nested connection sizes, so
           `cycles(first: 100) { issues(first: 250) }` scores ~25,000 against a
           10,000-point ceiling and is rejected outright.
        2. **Scoping.** A nested connection cannot carry the spec filter or the
           entity label, so cycle-backed reads would return other specs' issues
           and epics — and `move_incomplete_to_next` would happily reassign
           them.

        Going through `_search_scoped` means every cycle-backed read
        (`get_sprint_backlog`, metrics, velocity, rollover) is filtered exactly
        like every other read.
        """
        if self._cycles_cache is not None and not refresh:
            return self._cycles_cache

        cycles = self.transport.list_cycles()
        by_id = {c["id"]: c for c in cycles if c.get("id")}
        for c in by_id.values():
            c["issues"] = {"nodes": []}

        if by_id:
            # entity_type=None: cycle membership is the point of this read, so
            # tasks and bugs in a sprint count too — but an epic is a container,
            # not sprint work, and epics only look like issues here because
            # Linear has no separate epic entity. Drop those client-side.
            epic_label = self._entity_label("epic")
            # `search_issues` defaults to 200 rows — that default is per-call,
            # and here one call covers EVERY cycle. A team with 250 in-scope
            # issues across its cycles would silently lose the tail, emptying
            # older sprint backlogs and undercounting velocity, metrics, and
            # rollover candidates. Budget per cycle instead, and _paginate
            # warns rather than truncating quietly if even this is hit.
            issues = self._search_scoped(
                {"cycle": {"id": {"in": list(by_id)}}}, entity_type=None,
                max_results=max(_MAX_ISSUES_PER_CYCLE * len(by_id), 500),
            )
            for issue in issues:
                if epic_label in _label_names(issue):
                    continue
                cid = (issue.get("cycle") or {}).get("id")
                if cid in by_id:
                    by_id[cid]["issues"]["nodes"].append(issue)

        self._cycles_cache = cycles
        return self._cycles_cache

    def _search_scoped(self, filter_: Optional[dict] = None, *,
                       entity_type: Optional[str] = "story",
                       order_by: str = "updatedAt",
                       max_results: Optional[int] = None) -> list[dict]:
        """Search issues with the spec filter (and optionally the entity
        label) always applied.

        Single choke point so no read path can forget the spec scope — the
        cross-spec leak that cycle-backed reads had.
        """
        fragments = [self._spec_filter_fragment()]
        if entity_type:
            fragments.append(
                {"labels": {"name": {"eq": self._entity_label(entity_type)}}}
            )
        if filter_:
            fragments.append(filter_)
        merged = self._merge_filters(*fragments)
        if max_results is None:
            return self.transport.search_issues(merged, order_by=order_by)
        return self.transport.search_issues(
            merged, order_by=order_by, max_results=max_results
        )

    def _resolve_cycle(self, sprint_num: Optional[int]) -> Optional[dict]:
        """Resolve a synaptory sprint number to a Linear cycle.

        Cycle numbers are team-lifetime-monotonic and never restart, so a team
        already at cycle 47 has no cycle 1 for "Sprint 1" to bind to. The id
        map is therefore authoritative when present, with identity match on
        `cycle.number` as the fresh-team fallback.
        """
        if sprint_num is None:
            return None
        entry = self._load_id_map().get(f"SPRINT-{sprint_num}") or {}
        cycle_id = entry.get("linear_id")
        cycles = self._load_cycles()
        if cycle_id:
            for c in cycles:
                if c.get("id") == cycle_id:
                    return c
        for c in cycles:
            if c.get("number") == sprint_num:
                return c
        return None

    def list_sprints(self) -> list[SprintInfo]:
        out = []
        for c in self._load_cycles():
            num = self._sprint_number_for_cycle(c)
            if num is None:
                continue
            story_ids = self._extract_synaptory_ids(_cycle_issues(c))
            out.append(SprintInfo(
                number=num,
                goal=c.get("description") or c.get("name") or f"Sprint {num}",
                dates=f"{c.get('startsAt', '')} to {c.get('endsAt', '')}".strip(" to "),
                story_ids=story_ids,
                story_count=len(story_ids),
                tracker_id=c.get("id", ""),
            ))
        return sorted(out, key=lambda s: s.number)

    def _sprint_number_for_cycle(self, cycle: dict) -> Optional[int]:
        """Map a cycle back to its synaptory sprint number.

        Prefers an explicit SPRINT-N binding in the id map so a team whose
        cycle numbering is offset still reports the sprint numbers synaptory
        assigned; falls back to the cycle's own number.
        """
        for key, entry in self._load_id_map().items():
            if key.startswith("SPRINT-") and entry.get("linear_id") == cycle.get("id"):
                return _safe_int(key[len("SPRINT-"):])
        return cycle.get("number")

    def get_sprint(self, sprint_num: int) -> Optional[SprintInfo]:
        for s in self.list_sprints():
            if s.number == sprint_num:
                return s
        return None

    def create_sprint(self, sprint: SprintInfo) -> SprintInfo:
        """Bind to (or, when permitted, create) the cycle for this sprint.

        Idempotent: `tracker_cli` and the migrate path both re-fire creates, so
        an existing cycle is a no-op plus a best-effort goal update.

        Binding order:
          1. an existing SPRINT-N mapping, or a cycle whose number matches
          2. an explicit `sprint.tracker_id` (cycle uuid or number)
          3. the earliest unbound, unfinished cycle — this is what lets a
             synaptory project adopt a team that is already at cycle 47, where
             no `cycle.number == 1` exists to match
          4. `cycleCreate`, only with `manage_cycles: true`
        """
        existing = self._bind_cycle_for_sprint(sprint)

        if existing:
            if sprint.goal and sprint.goal != existing.get("description"):
                try:
                    self.transport.update_cycle(
                        existing["id"], {"description": sprint.goal}
                    )
                except AdapterError:
                    pass  # goal text is cosmetic; binding already succeeded
            self._save_sprint_mapping(sprint.number, existing)
            self._cycles_cache = None
            return self.get_sprint(sprint.number) or sprint

        if not self._manage_cycles:
            raise AdapterError(
                f"Sprint {sprint.number} has no Linear cycle to bind to, and "
                "every existing cycle is already bound or finished. Linear "
                "creates cycles automatically on the team's configured cadence "
                "— wait for the next cycle, pass an explicit cycle via "
                "SprintInfo.tracker_id, or set "
                "`tracker.linear.manage_cycles: true` to let Synaptory call "
                "cycleCreate (which may conflict with that cadence)."
            )

        input_ = {"name": f"Sprint {sprint.number}"}
        if sprint.goal:
            input_["description"] = sprint.goal
        # CycleCreateInput.startsAt / endsAt are non-null in Linear's schema,
        # so they must always be sent — deriving a window when the caller
        # didn't supply one, rather than failing GraphQL validation.
        start, end = self._cycle_window(sprint.dates)
        input_["startsAt"] = start
        input_["endsAt"] = end

        cycle = self.transport.create_cycle(input_)
        self._save_sprint_mapping(sprint.number, cycle)
        self._load_cycles(refresh=True)
        return self.get_sprint(sprint.number) or sprint

    def _bind_cycle_for_sprint(self, sprint: SprintInfo) -> Optional[dict]:
        """Choose the cycle a sprint should bind to.

        Deliberately *not* `_resolve_cycle`: that helper's numeric fallback
        matches any cycle with the same number, including long-finished
        history. On a team at cycle 47 whose cycle 1 completed a year ago,
        binding Sprint 1 through it silently picked the dead cycle 1 — and,
        because the match succeeded, an explicit `tracker_id` never got a say.

        Order: the id map is authoritative, then an explicit `tracker_id`,
        then a numeric match *only* when that cycle is unbound and unfinished,
        then the earliest unbound unfinished cycle.
        """
        cycles = self._load_cycles()

        entry = self._load_id_map().get(f"SPRINT-{sprint.number}") or {}
        mapped_id = entry.get("linear_id")
        if mapped_id:
            for c in cycles:
                if c.get("id") == mapped_id:
                    return c

        if sprint.tracker_id:
            hit = self._cycle_by_ref(str(sprint.tracker_id))
            if hit is None:
                raise AdapterError(
                    f"Sprint {sprint.number}: tracker_id "
                    f"{sprint.tracker_id!r} matches no cycle on team "
                    f"{self.team_key!r}."
                )
            return hit

        bound = self._bound_cycle_ids()
        for c in cycles:
            if (c.get("number") == sprint.number
                    and c.get("id") not in bound
                    and not c.get("completedAt")):
                return c

        return self._first_unbound_cycle()

    def _bound_cycle_ids(self) -> set:
        """Cycle ids already claimed by some sprint."""
        return {
            entry.get("linear_id")
            for key, entry in self._load_id_map().items()
            if key.startswith("SPRINT-") and entry.get("linear_id")
        }

    def _cycle_by_ref(self, ref: str) -> Optional[dict]:
        """Find a cycle by uuid or by its Linear cycle number."""
        num = _safe_int(ref)
        for c in self._load_cycles():
            if c.get("id") == ref or (num is not None and c.get("number") == num):
                return c
        return None

    def _first_unbound_cycle(self) -> Optional[dict]:
        """Earliest cycle not already bound to a sprint and not finished.

        Deterministic adoption path for a team whose cycle numbering is offset
        from synaptory's sprint numbering. Sprints are created in ascending
        order, so successive calls walk successive cycles.
        """
        bound = self._bound_cycle_ids()
        candidates = [
            c for c in self._load_cycles()
            if c.get("id") not in bound and not c.get("completedAt")
        ]
        return min(candidates, key=lambda c: c.get("number") or 0, default=None)

    def _cycle_window(self, dates: str) -> tuple:
        """Return (startsAt, endsAt) ISO strings for a new cycle.

        Uses the caller's `SprintInfo.dates` when both ends are present;
        otherwise starts after the latest known cycle (or now) and runs for
        `tracker.linear.cycle_length_days`.
        """
        from datetime import datetime, timedelta, timezone

        start_raw, end_raw = _split_dates(dates)
        if start_raw and end_raw:
            return _iso(start_raw), _iso(end_raw)

        now = datetime.now(timezone.utc)
        start = _parse_iso(start_raw) or now
        for c in self._load_cycles():
            ends = _parse_iso(c.get("endsAt") or "")
            if ends and ends > start:
                start = ends
        end = _parse_iso(end_raw) or (start + timedelta(days=self._cycle_length_days))
        return (start.isoformat().replace("+00:00", "Z"),
                end.isoformat().replace("+00:00", "Z"))

    def get_sprint_backlog(self, sprint_num: int) -> list[Story]:
        cycle = self._resolve_cycle(sprint_num)
        if not cycle:
            return []
        return [self._issue_to_story(i) for i in _cycle_issues(cycle)]

    def assign_to_sprint(self, story_id: str, sprint_num: int) -> Story:
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            raise AdapterError(f"Story not found: {story_id}")
        cycle = self._resolve_cycle(sprint_num)
        if not cycle:
            raise AdapterError(
                f"Sprint {sprint_num} has no matching Linear cycle — run "
                "create-sprint first."
            )
        self.transport.update_issue(linear_id, {"cycleId": cycle["id"]})
        self._cycles_cache = None
        return self.get_story(story_id) or Story(id=story_id, title="")

    def remove_from_sprint(self, story_id: str, sprint_num: int) -> Story:
        linear_id = self._resolve_id(story_id)
        if not linear_id:
            raise AdapterError(f"Story not found: {story_id}")
        self.transport.update_issue(linear_id, {"cycleId": None})
        self._cycles_cache = None
        return self.get_story(story_id) or Story(id=story_id, title="")

    def close_sprint(self, sprint_num: int) -> SprintInfo:
        """Report the cycle as closed; never raise on an already-closed one.

        Linear has no close-cycle mutation — cycles complete on their end date.
        With `manage_cycles` on we can pull `endsAt` forward to now; otherwise
        this is a read.
        """
        cycle = self._resolve_cycle(sprint_num)
        if not cycle:
            return SprintInfo(number=sprint_num, goal=f"Sprint {sprint_num}")

        if self._manage_cycles and not cycle.get("completedAt"):
            try:
                from datetime import datetime, timezone
                now = datetime.now(timezone.utc).isoformat()
                if (cycle.get("endsAt") or "") > now:
                    self.transport.update_cycle(cycle["id"], {"endsAt": now})
                    self._load_cycles(refresh=True)
            except (AdapterError, ValueError):
                pass  # already complete, or Linear refused — report, don't fail

        return self.get_sprint(sprint_num) or SprintInfo(
            number=sprint_num, goal=f"Sprint {sprint_num}"
        )

    def move_incomplete_to_next(self, from_sprint: int, to_sprint: int) -> list[Story]:
        source = self._resolve_cycle(from_sprint)
        target = self._resolve_cycle(to_sprint)
        if not source or not target:
            return []

        moved = []
        for issue in _cycle_issues(source):
            state_type = (issue.get("state") or {}).get("type", "")
            if state_type in _TERMINAL_STATE_TYPES:
                continue
            # Linear may have rolled the issue over natively already.
            if (issue.get("cycle") or {}).get("id") == target["id"]:
                continue
            try:
                self.transport.update_issue(issue["id"], {"cycleId": target["id"]})
                moved.append(self._issue_to_story(issue))
            except AdapterError as e:
                print(
                    f"tracker(linear): could not move "
                    f"{issue.get('identifier', issue.get('id'))} to cycle "
                    f"{to_sprint}: {e}",
                    file=sys.stderr,
                )
        self._cycles_cache = None
        return moved

    def get_sprint_metrics(self, sprint_num: int) -> SprintMetrics:
        stories = self.get_sprint_backlog(sprint_num)
        planned = len(stories)
        completed = sum(1 for s in stories if s.status == "DONE")
        in_progress = sum(1 for s in stories if s.status in ("IN_PROGRESS", "IN_REVIEW",
                                                             "AWAITING_ACCEPTANCE"))
        blocked = sum(1 for s in stories if s.status == "BLOCKED")
        return SprintMetrics(
            planned=planned, completed=completed,
            in_progress=in_progress, blocked=blocked,
            velocity=float(completed),
        )

    # ── Backlog Operations ───────────────────────────────────

    def get_backlog(self) -> list[BacklogItem]:
        issues = self._search_scoped(order_by="createdAt")
        return [self._issue_to_backlog_item(i) for i in issues]

    def query_tickets(self, query_filter: QueryFilter) -> list[BacklogItem]:
        fragments = [self._spec_filter_fragment()]

        if query_filter.status:
            # Statuses split across two axes: most map to a WorkflowState, but
            # BLOCKED (and CANCELLED on a team with no canceled state) are
            # label-backed. Resolving only the state axis and dropping the rest
            # silently widened the query to *every* ticket — the same
            # scope-leak class as the unresolvable-sprint case below.
            state_ids, label_names, unresolved = [], [], []
            for s in query_filter.status:
                marker = STATUS_LABELS.get(s)
                state = self._resolve_state(s)
                if state:
                    state_ids.append(state["id"])
                elif marker:
                    label_names.append(marker)
                else:
                    unresolved.append(s)

            clauses = []
            if state_ids:
                clauses.append({"state": {"id": {"in": state_ids}}})
            if label_names:
                clauses.append({"labels": {"name": {"in": label_names}}})

            if not clauses:
                print(
                    f"tracker(linear): none of the requested statuses "
                    f"{sorted(set(query_filter.status))} resolve on team "
                    f"{self.team_key!r} — returning no tickets rather than "
                    "dropping the status filter",
                    file=sys.stderr,
                )
                return []
            if unresolved:
                print(
                    f"tracker(linear): status {sorted(set(unresolved))} does not "
                    f"resolve on team {self.team_key!r}; querying the rest",
                    file=sys.stderr,
                )
            # A status request is a disjunction — match any of them.
            fragments.append(clauses[0] if len(clauses) == 1 else {"or": clauses})

        if query_filter.priority:
            prios = [PRIORITY_MAP[p] for p in query_filter.priority if p in PRIORITY_MAP]
            if prios:
                fragments.append({"priority": {"in": prios}})

        if query_filter.ticket_type:
            type_labels = [self._entity_label(t) for t in query_filter.ticket_type]
            if type_labels:
                fragments.append({"labels": {"name": {"in": type_labels}}})

        if query_filter.sprint is not None:
            cycle = self._resolve_cycle(query_filter.sprint)
            if not cycle:
                # #187 — an unresolvable sprint must NOT be silently dropped:
                # doing so widens the query to every ticket (e.g.
                # `--sprint N --mine` would return all of the user's tickets
                # across all sprints). An unknown sprint has no tickets.
                print(
                    f"tracker(linear): sprint {query_filter.sprint} not found — "
                    "returning no tickets rather than dropping the sprint filter",
                    file=sys.stderr,
                )
                return []
            fragments.append({"cycle": {"id": {"eq": cycle["id"]}}})

        if query_filter.text:
            fragments.append({"title": {"containsIgnoreCase": query_filter.text}})

        if query_filter.assignee:
            fragments.append(self._assignee_fragment(query_filter.assignee))

        issues = self.transport.search_issues(self._merge_filters(*fragments))
        return [self._issue_to_backlog_item(i) for i in issues]

    @staticmethod
    def _assignee_fragment(assignee: str) -> dict:
        """Build the assignee filter, resolving the `currentUser()` sentinel.

        Linear answers this server-side via `isMe`, so unlike Teamwork there
        is no extra round trip to look up the caller's own id.
        """
        if assignee == "currentUser()":
            return {"assignee": {"isMe": {"eq": True}}}
        if "@" in assignee:
            return {"assignee": {"email": {"eq": assignee}}}
        return {"assignee": {"name": {"eqIgnoreCase": assignee}}}

    # ── Reporting Operations ─────────────────────────────────

    def get_velocity_data(self, num_sprints: int = 0) -> list[dict]:
        """Velocity per sprint, computed from the one cycles document.

        Cycles arrive with their issues attached, so this is a single API
        call regardless of sprint count — see `_load_cycles`.
        """
        data = []
        for c in sorted(self._load_cycles(), key=lambda c: c.get("number") or 0):
            num = self._sprint_number_for_cycle(c)
            if num is None:
                continue
            issues = _cycle_issues(c)
            completed = sum(
                1 for i in issues
                if (i.get("state") or {}).get("type") == "completed"
            )
            data.append({
                "sprint": num,
                "planned": len(issues),
                "completed": completed,
            })
        if num_sprints > 0:
            data = data[-num_sprints:]
        return data

    def get_sprint_report_data(self, sprint_num: int) -> dict:
        metrics = self.get_sprint_metrics(sprint_num)
        sprint = self.get_sprint(sprint_num)
        stories = self.get_sprint_backlog(sprint_num)
        return {
            "sprint_num": sprint_num,
            "sprint_goal": sprint.goal if sprint else f"Sprint {sprint_num}",
            "stories": {
                "planned": metrics.planned,
                "completed": metrics.completed,
                "in_progress": metrics.in_progress,
                "blocked": metrics.blocked,
                "completion_pct": round(
                    (metrics.completed / metrics.planned * 100) if metrics.planned > 0 else 0
                ),
                "status_by_story": [
                    {"id": s.id, "title": s.title, "status": s.status,
                     "priority": s.priority, "size": s.size, "feature": s.feature}
                    for s in stories
                ],
            },
        }

    def get_burndown_data(self, sprint_num: int) -> list[dict]:
        # Linear renders cycle burndown/progress natively in its own UI; there
        # is no historical-snapshot endpoint worth reconstructing here.
        # Same posture as the Jira adapter.
        return []

    # ── Private Helpers ──────────────────────────────────────

    def _resolve_template_path(self, entity_type: str) -> str:
        """Resolve a template path from config.templates by entity type."""
        templates_cfg = getattr(self.config, "templates", None)
        if not templates_cfg:
            return ""
        return getattr(templates_cfg, entity_type, "") or ""

    def _label_ids(self, names: list) -> list:
        """Resolve label names to Linear label ids, creating any that are new."""
        ids = []
        for name in names:
            if not name:
                continue
            try:
                ids.append(self.transport.get_or_create_label(name))
            except AdapterError as e:
                print(
                    f"tracker(linear): could not resolve label {name!r}: {e}",
                    file=sys.stderr,
                )
        return ids

    def _issue_to_epic(self, issue: dict) -> Epic:
        synaptory_id = self._extract_synaptory_id(issue)
        return Epic(
            id=synaptory_id or issue.get("identifier", ""),
            title=issue.get("title", ""),
            tracker_id=issue.get("identifier", ""),
            tracker_url=issue.get("url", ""),
        )

    def _issue_to_story(self, issue: dict) -> Story:
        synaptory_id = self._extract_synaptory_id(issue)
        status = self._canonical_from_issue(issue)

        priority = PRIORITY_REVERSE.get(issue.get("priority"), "")
        size = self._estimate_to_size(issue.get("estimate"))

        # Epic + feature linkage are labels, not parent/child relations.
        epic_id, feature = "", ""
        for name in _label_names(issue):
            if not epic_id and _EPIC_ID_RE.match(name):
                epic_id = name
            elif not feature and _FEATURE_ID_RE.match(name):
                feature = name

        sprint_str = ""
        cycle = issue.get("cycle")
        if isinstance(cycle, dict):
            num = self._sprint_number_for_cycle(cycle)
            if num is not None:
                sprint_str = str(num)

        acs = self._parse_acs_from_description(issue.get("description") or "")

        assignee_field = issue.get("assignee")
        assignee_value = None
        if isinstance(assignee_field, dict):
            assignee_value = assignee_field.get("email") or assignee_field.get("name")

        return Story(
            id=synaptory_id or issue.get("identifier", ""),
            title=issue.get("title", ""),
            feature=feature,
            epic=epic_id,
            status=status,
            priority=priority,
            size=size,
            sprint=sprint_str,
            ac_count=len(acs),
            acceptance_criteria=acs,
            assignee=assignee_value,
            tracker_id=issue.get("identifier", ""),
            tracker_url=issue.get("url", ""),
        )

    def _issue_to_backlog_item(self, issue: dict) -> BacklogItem:
        story = self._issue_to_story(issue)
        return BacklogItem(
            id=story.id, title=story.title, feature=story.feature,
            priority=story.priority, status=story.status,
            size=story.size, sprint=story.sprint, assignee=story.assignee,
        )

    def _extract_synaptory_id(self, issue: dict) -> str:
        """Extract the issue's *own* synaptory ID.

        Order matters here, and differs from the Jira adapter's.

        Because epic linkage is label-only, a story carries **two** ID-shaped
        labels: its own `US-037` and its epic's `EPIC-001` (plus possibly
        `FEAT-003`). Returning the first match would make a story identify
        itself as its epic, and Linear does not guarantee label order — so the
        bug would surface intermittently.

        1. The `> synaptory: US-037` description line is authoritative: we
           write it at create time with the entity's own id, and Linear stores
           descriptions as raw Markdown so it round-trips losslessly (on Jira,
           ADF mangles it — which is why Jira treats it as a mere fallback).
        2. Otherwise fall back to labels, disambiguated by the entity label:
           an `hc:epic` issue wants its `EPIC-` label, anything else wants the
           label that is *not* epic/feature linkage.
        """
        description = issue.get("description")
        if isinstance(description, str):
            m = re.search(r'synaptory:\s*`?(\S+?)`?(?:\s|$)', description)
            if m and _SYNAPTORY_ID_RE.match(m.group(1)):
                return m.group(1)

        names = _label_names(issue)
        candidates = [n for n in names if _SYNAPTORY_ID_RE.match(n)]
        if not candidates:
            return ""
        if len(candidates) == 1:
            return candidates[0]

        # Multiple ID-shaped labels — pick by the issue's own entity kind.
        if self._entity_label("epic") in names:
            for n in candidates:
                if _EPIC_ID_RE.match(n):
                    return n
        own = [n for n in candidates
               if not _EPIC_ID_RE.match(n) and not _FEATURE_ID_RE.match(n)]
        if own:
            return own[0]
        return candidates[0]

    def _extract_synaptory_ids(self, issues: list) -> list:
        return [hid for i in issues if (hid := self._extract_synaptory_id(i))]

    @staticmethod
    def _parse_acs_from_description(text: str) -> list[AcceptanceCriterion]:
        """Parse acceptance criteria from description text."""
        acs = []
        for line in text.splitlines():
            stripped = line.strip()
            # Match: - [ ] AC-1: text  or  - [x] **AC-1: text**
            m = re.match(r'- \[([xX ])\]\s*\*?\*?AC-(\w+):?\s*(.*?)\*?\*?\s*$', stripped)
            if m:
                acs.append(AcceptanceCriterion(
                    id=f"AC-{m.group(2)}",
                    text=m.group(3).strip(),
                    met=m.group(1).lower() == "x",
                ))
                continue
            # Match: **AC-1 — title:** or **AC-1: text**
            m2 = re.match(r'\*\*AC-(\w+)\s*[—–\-:]?\s*(.*?)\*\*', stripped)
            if m2:
                acs.append(AcceptanceCriterion(
                    id=f"AC-{m2.group(1)}",
                    text=m2.group(2).strip().rstrip(":").strip(),
                ))
        return acs

    # ── ID map ───────────────────────────────────────────────

    def _load_id_map(self) -> dict:
        if self._id_map is not None:
            return self._id_map
        if self._id_map_path.exists():
            try:
                self._id_map = json.loads(self._id_map_path.read_text(encoding="utf-8"))
            except Exception:
                self._id_map = {}
        else:
            self._id_map = {}
        return self._id_map

    def _save_id_mapping(self, synaptory_id: str, linear_id: str,
                         identifier: str = "", url: str = "") -> None:
        """Persist the uuid *and* the human identifier.

        Mutations need the uuid; the identifier is kept for diagnostics and
        for cross-checking the `> synaptory:` description line.
        """
        id_map = self._load_id_map()
        id_map[synaptory_id] = {
            "linear_id": linear_id,
            "linear_identifier": identifier,
            "linear_url": url,
        }
        self._write_id_map(id_map)

    def _save_sprint_mapping(self, sprint_num: int, cycle: dict) -> None:
        id_map = self._load_id_map()
        id_map[f"SPRINT-{sprint_num}"] = {
            "linear_id": cycle.get("id", ""),
            "linear_number": cycle.get("number"),
        }
        self._write_id_map(id_map)

    def _write_id_map(self, id_map: dict) -> None:
        self._id_map_path.parent.mkdir(parents=True, exist_ok=True)
        self._id_map_path.write_text(json.dumps(id_map, indent=2), encoding="utf-8")

    def _resolve_id(self, synaptory_id: str) -> Optional[str]:
        """Resolve a synaptory ID to a Linear issue uuid."""
        entry = self._load_id_map().get(synaptory_id)
        if entry:
            return entry.get("linear_id")
        return None


# ── Module-level helpers ─────────────────────────────────────────────────

def _label_names(issue: dict) -> list:
    """Return an issue's label names from the Relay connection shape."""
    return [
        n.get("name", "")
        for n in ((issue.get("labels") or {}).get("nodes") or [])
        if isinstance(n, dict) and n.get("name")
    ]


def _cycle_issues(cycle: dict) -> list:
    """Return a cycle's issues from the Relay connection shape."""
    return list((cycle.get("issues") or {}).get("nodes") or [])


def _safe_int(value) -> Optional[int]:
    try:
        return int(str(value).strip())
    except (ValueError, TypeError):
        return None


def _looks_like_uuid(value: str) -> bool:
    return bool(re.fullmatch(
        r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-'
        r'[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', value or ""
    ))


def _split_dates(dates: str) -> tuple:
    """Split a `SprintInfo.dates` string ('<start> to <end>') into its parts."""
    if not dates:
        return "", ""
    parts = [p.strip() for p in dates.split(" to ", 1)]
    if len(parts) == 2:
        return parts[0], parts[1]
    return parts[0], ""


def _parse_iso(value: str):
    """Parse an ISO-8601 date/datetime into an aware datetime, or None.

    Accepts the plain `YYYY-MM-DD` that `SprintInfo.dates` usually carries as
    well as the full timestamps Linear returns.
    """
    from datetime import datetime, timezone
    if not value:
        return None
    text = str(value).strip().replace("Z", "+00:00")
    try:
        dt = datetime.fromisoformat(text)
    except ValueError:
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def _iso(value: str) -> str:
    """Normalize a date string to an ISO-8601 UTC timestamp for Linear."""
    dt = _parse_iso(value)
    if dt is None:
        return value
    return dt.isoformat().replace("+00:00", "Z")
